import json, itertools

def mul(a, b):
    return (a[0]*b[0]-a[1]*b[1], a[0]*b[1]+a[1]*b[0])
def add(a, b):
    return (a[0]+b[0], a[1]+b[1])
def sub(a, b):
    return (a[0]-b[0], a[1]-b[1])

def coeffs_from_roots(roots):
    # coefficients low->high, monic, built by Vieta-style expansion
    c = [(1, 0)]
    for r in roots:
        new = [(0, 0)] * (len(c) + 1)
        for i, ci in enumerate(c):
            new[i+1] = add(new[i+1], ci)                 # z * term
            new[i] = sub(new[i], mul(r, ci))             # -r * term
        c = new
    return c

def horner(c, z):
    acc = (0, 0)
    for ci in reversed(c):
        acc = add(mul(acc, z), ci)
    return acc

def prod_form(roots, z):
